export interface PatientRow {
  id: string;
  org_id: string;
  user_id: string | null;
  first_name: string;
  last_name: string;
  date_of_birth: Date;
  email: string | null;
  phone: string | null;
  mrn: string;
  reason_for_care: string | null;
  created_at: Date;
}

